def transform(grid):
    """Connect collinear occurrences of the single foreground color with 2."""
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    # The background is the most common color; 2 is the bridge color in outputs.
    bg = max(colors, key=lambda c: sum(row.count(c) for row in grid))
    foreground = [c for c in colors if c != bg and c != 2]
    if not foreground:
        return [row[:] for row in grid]
    color = foreground[0]
    out = [row[:] for row in grid]
    # Fill only the original background between consecutive markers in each row.
    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == color]
        for a, b in zip(positions, positions[1:]):
            if all(grid[r][c] == bg for c in range(a + 1, b)):
                for c in range(a + 1, b): out[r][c] = 2
    # Fill only the original background between consecutive markers in each column.
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == color]
        for a, b in zip(positions, positions[1:]):
            if all(grid[r][c] == bg for r in range(a + 1, b)):
                for r in range(a + 1, b): out[r][c] = 2
    return out

def transform(grid):
    """Complete the broken horizontal and vertical strokes of the foreground figure."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    foregrounds = [value for value in counts if value not in (background, 2)]
    if not foregrounds:
        return [row[:] for row in grid]
    # These puzzles use one non-background marker color.
    foreground = max(foregrounds, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == foreground]
    if not points:
        return [row[:] for row in grid]
    rmin = min(r for r, c in points)
    rmax = max(r for r, c in points)
    cmin = min(c for r, c in points)
    cmax = max(c for r, c in points)
    out = [row[:] for row in grid]

    # The upper and lower strokes span the figure's horizontal bounds.
    for r in {rmin, rmax}:
        for c in range(cmin, cmax + 1):
            if grid[r][c] == background:
                out[r][c] = 2

    # Complete the two outer sides, and any clearly established interior
    # vertical stroke (at least three marker cells define such a stroke).
    for c in range(cmin, cmax + 1):
        rows = [r for r in range(h) if grid[r][c] == foreground]
        if c in (cmin, cmax):
            lo, hi = rmin, rmax
        elif len(rows) >= 3:
            lo, hi = min(rows), max(rows)
        else:
            continue
        for r in range(lo, hi + 1):
            if grid[r][c] == background:
                out[r][c] = 2
    return out

