def transform(grid):
    """Bridge gaps on any row or column containing at least three markers."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    foregrounds = [v for v in counts if v != background and v != 2]
    if not foregrounds:
        return [row[:] for row in grid]
    marker = max(foregrounds, key=lambda v: counts[v])
    out = [row[:] for row in grid]

    # A line is an intended stroke when it contains at least three markers.
    # Keep the original markers and paint only the gaps between its extremes.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 3:
            for c in range(min(cols), max(cols) + 1):
                if out[r][c] == background:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if len(rows) >= 3:
            for r in range(min(rows), max(rows) + 1):
                if out[r][c] == background:
                    out[r][c] = 2
    return out

