from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Mark zero cells reachable from the edge using 4-way movement.
    exterior = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not exterior[r][c]:
                exterior[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not exterior[r][c]:
                exterior[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and not exterior[nr][nc]):
                exterior[nr][nc] = True
                q.append((nr, nc))

    # Find each 4-connected wall component. Only components bordering an
    # enclosed zero region are active for recoloring.
    seen_ones = [[False] * w for _ in range(h)]
    active_components = []
    cardinal = ((1, 0), (-1, 0), (0, 1), (0, -1))
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or seen_ones[r][c]:
                continue
            seen_ones[r][c] = True
            q = deque([(r, c)])
            component = []
            while q:
                x, y = q.popleft()
                component.append((x, y))
                for dr, dc in cardinal:
                    nx, ny = x + dr, y + dc
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1
                            and not seen_ones[nx][ny]):
                        seen_ones[nx][ny] = True
                        q.append((nx, ny))
            encloses = any(
                0 <= x + dr < h and 0 <= y + dc < w
                and grid[x + dr][y + dc] == 0 and not exterior[x + dr][y + dc]
                for x, y in component for dr, dc in cardinal
            )
            if encloses:
                active_components.append(component)

    # Recolor the 8-neighbor rim: enclosed side is 3, exterior side is 2.
    for component in active_components:
        for r, c in component:
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r + dr, c + dc
                    if (dr or dc) and 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0:
                        out[nr][nc] = 2 if exterior[nr][nc] else 3
    return out

def transform(grid):
    """Color the empty tail after any horizontal row segment with red (1)."""
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    for row in out:
        occupied = [i for i, value in enumerate(row) if value != bg]
        if occupied:
            for i in range(max(occupied) + 1, len(row)):
                row[i] = 1
    return out

from collections import Counter


def transform(grid):
    """Highlight missing or extra right-edge pixels in repeated row patterns."""
    out = [row[:] for row in grid]
    flat = [value for row in grid for value in row]
    if not flat:
        return out

    background = Counter(flat).most_common(1)[0][0]
    non_background = [value for value in flat if value != background]
    if not non_background:
        return out
    color = Counter(non_background).most_common(1)[0][0]
    height, width = len(grid), len(grid[0])

    # Fully colored rows act as complete reference lines. Other colored rows
    # are grouped into repeated multi-row patterns separated by background.
    full_rows = [r for r, row in enumerate(grid)
                 if all(value == color for value in row)]
    partial_rows = [r for r, row in enumerate(grid)
                    if any(value == color for value in row)
                    and not all(value == color for value in row)]
    groups = []
    for r in partial_rows:
        if not groups or r > groups[-1][-1] + 1:
            groups.append([r])
        else:
            groups[-1].append(r)

    # Align two repeated multi-row patterns by their horizontal translation.
    if len(groups) == 2 and len(groups[0]) == len(groups[1]) and len(groups[0]) > 1:
        first, second = groups
        best = None
        for shift in range(-width + 1, width):
            intersection = union = 0
            for ra, rb in zip(first, second):
                for c in range(width):
                    a_is_color = grid[ra][c] == color
                    d = c + shift
                    b_is_color = 0 <= d < width and grid[rb][d] == color
                    intersection += int(a_is_color and b_is_color)
                    union += int(a_is_color or b_is_color)
            score = (intersection / union if union else 0,
                     intersection, -abs(shift), shift)
            if best is None or score > best:
                best = score

