            border=[g[y][x] for y,x in cells if y in (r0,r1) or x in (c0,c1)]
            outer=Counter(border).most_common(1)[0][0]
            mids_r={(r0+r1)//2,(r0+r1+1)//2}
            mids_c={(c0+c1)//2,(c0+c1+1)//2}
