                        count = (pref_same[r2][c2] - pref_same[r1][c2]
                                 - pref_same[r2][c1] + pref_same[r1][c1])
                        if count < 0.75 * area:
                            continue
                        filled = (pref_nonbg[r2][c2] - pref_nonbg[r1][c2]
                                  - pref_nonbg[r2][c1] + pref_nonbg[r1][c1])
                        if filled != area:
                            continue
                        for r in range(r1, r2):
                            for c in range(c1, c2):
                                out[r][c] = color
    return out

def transform(grid):
    out = [row[:] for row in grid]
    if not grid:
        return out
    last = len(grid) - 1
    # The 5s on the bottom row are upward-running markers. Each marker
    # carries its current color upward, changing color when it meets a
    # nonzero cell in its column.
    for c, value in enumerate(grid[last]):
        if value == 5:
            color = value
            for r in range(last, -1, -1):
                if grid[r][c] != 0:
                    color = grid[r][c]
                else:
                    out[r][c] = color
    return out

def transform(grid):
    """Expand the top-row marker into diagonal fronts and a periodic inner fill."""
    width = len(grid[0])
    marker = next(c for c, value in enumerate(grid[0]) if value == 2)
    out = [[0 for _ in range(width)] for _ in range(width)]
    for r in range(width):
        for c in range(width):
            if abs(c - marker) == r:
                out[r][c] = 2
            elif abs(c - marker) < r and (c - r - marker) % 4 == 0:
                out[r][c] = 1
    return out

from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    counts = {3: 0, 2: 0}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in counts or seen[r][c]:
                continue
            counts[color] += 1
            seen[r][c] = True
            q = deque([(r, c)])
            while q:
                y, x = q.popleft()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
    cells = [3] * counts[3] + [2] * counts[2]
    cells = (cells + [0] * 6)[:6]
    return [cells[:3], cells[3:]]

def transform(grid):
    """Fill background cells lying between equal non-background markers in rows or columns."""
    from collections import Counter
    out = [list(row) for row in grid]
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    # Each non-background color acts as a marker; interpolate between consecutive markers.
    for r in range(h):
        for color in set(grid[r]):
            if color == bg:
                continue
            pts = [c for c, v in enumerate(grid[r]) if v == color]
            for a, b in zip(pts, pts[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 3
    for c in range(w):
        colors = {grid[r][c] for r in range(h)} - {bg}
        for color in colors:
            pts = [r for r in range(h) if grid[r][c] == color]
            for a, b in zip(pts, pts[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 3
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full single-color rows and columns mark the partition lines.
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    separator_colors = [grid[r][0] for r in sep_rows] + [grid[0][c] for c in sep_cols]
    sep_color = max(set(separator_colors), key=separator_colors.count) if separator_colors else None
    row_cuts = [-1] + sep_rows + [h]
    col_cuts = [-1] + sep_cols + [w]
    row_bands = [(a + 1, b) for a, b in zip(row_cuts, row_cuts[1:]) if b > a + 1]
    col_bands = [(a + 1, b) for a, b in zip(col_cuts, col_cuts[1:]) if b > a + 1]
    blocks = []
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            blocks.append((r0, r1, c0, c1))
    # The repeated block is the one with the most distinct non-background colors.
    vals = [grid[r][c] for r0, r1, c0, c1 in blocks for r in range(r0, r1) for c in range(c0, c1)]
    bg = collections.Counter(vals).most_common(1)[0][0]
    def score(b):
        r0, r1, c0, c1 = b
        cells = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)]
        return (sum(v != bg for v in cells), len(set(cells)))
    template = max(blocks, key=score)
    tr0, tr1, tc0, tc1 = template
    out = [row[:] for row in grid]
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            if r1-r0 != tr1-tr0 or c1-c0 != tc1-tc0:
                continue
            for dr in range(r1-r0):
                for dc in range(c1-c0):
                    out[r0+dr][c0+dc] = grid[tr0+dr][tc0+dc]
    return out

