def transform(grid):
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0}
    tiles = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if square <= occupied:
                tiles.append((square, 1))
            # Color each three-cell L by the missing corner.
            corner_colors = {
                (r, c): 2,          # missing top-left
                (r, c + 1): 4,      # missing top-right
                (r + 1, c): 3,      # missing bottom-left
                (r + 1, c + 1): 5,  # missing bottom-right
            }
            for missing, color in corner_colors.items():
                shape = square - {missing}
                if shape <= occupied:
                    tiles.append((shape, color))

    by_cell = {cell: [] for cell in occupied}
    for shape, color in tiles:
        for cell in shape:
            by_cell[cell].append((shape, color))

    def cover(remaining):
        if not remaining:
            return []
        # Choose the most constrained uncovered cell first.
        cell = min(remaining, key=lambda p: sum(shape <= remaining for shape, _ in by_cell[p]))
        for shape, color in by_cell[cell]:
            if shape <= remaining:
                rest = cover(remaining - shape)
                if rest is not None:
                    return [(shape, color)] + rest
        return None

    pieces = cover(occupied)
    if pieces is None:
        raise ValueError("Input cannot be tiled by 2x2 squares and L triominoes")
    result = [[0] * w for _ in range(h)]
    for shape, color in pieces:
        for r, c in shape:
            result[r][c] = color
    return result

from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    up = down = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            minr = min(y for y, x in comp)
            maxr = max(y for y, x in comp)
            minc = min(x for y, x in comp)
            maxc = max(x for y, x in comp)
            cells = {(y - minr, x - minc) for y, x in comp}
            if (maxr - minr, maxc - minc) == (1, 2) and len(cells) == 4:
                # Stem above the three-cell bar maps to 3; stem below maps to 1.
                if {(0, 1), (1, 0), (1, 1), (1, 2)} == cells:
                    up += 1
                elif {(0, 0), (0, 1), (0, 2), (1, 1)} == cells:
                    down += 1
                else:
                    raise ValueError("Unexpected 4-cell component")
            else:
                raise ValueError("Unexpected component shape")
    out = [[0] * 6 for _ in range(3)]
    slots = ((0, 0), (2, 0), (0, 2), (2, 2))
    for i in range(up):
        r, c = slots[i]
        out[r][c] = 3
    for i in range(down):
        r, c = slots[i]
        out[r][c + 3] = 1
    return out

def transform(grid):
    """Shift all non-background cells down by one row."""
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    if not rows or not cols:
        return [row[:] for row in grid]
    values = [v for row in grid for v in row]
    background = max(set(values), key=values.count)
    out = [[background for _ in range(cols)] for _ in range(rows)]
    for r in range(rows - 1):
        for c in range(cols):
            if grid[r][c] != background:
                out[r + 1][c] = grid[r][c]
    return out

