def transform(grid):
    """Extend the middle row and column of every solid 3x3 block."""
    h, w = len(grid), len(grid[0])
    crosses = []
    seen = set()
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[i][j] == color
                   for i in range(r, r + 3)
                   for j in range(c, c + 3)):
                center = (r + 1, c + 1, color)
                if center not in seen:
                    seen.add(center)
                    crosses.append(center)

    # Paint each cross. Where differently colored crosses meet, leave a gap.
    owners = {}
    for cr, cc, color in crosses:
        for j in range(w):
            owners.setdefault((cr, j), set()).add(color)
        for i in range(h):
            owners.setdefault((i, cc), set()).add(color)
    out = [row[:] for row in grid]
    for (r, c), colors in owners.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
